    std::array<bool, MAX_MODULE_DEVICE_NUM + 1> baseCommInited_{};
    std::mutex opHcomInfosMutex_;

    std::mutex mutex_;
    std::mutex ccuMsCommMutex_;
};
} // namespace hccl
#endif // COLL_COMM_MGR_H

